{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.sku_live_mech_v2 as WITH data AS ( SELECT CASE WHEN UPPER(TRIM(sku)) like \'SN%\' or UPPER(TRIM(sku)) like \'BP%\' THEN UPPER(TRIM(sku)) WHEN UPPER(TRIM(sku)) LIKE \'MP%\' THEN UPPER( TRIM( REGEXP_SUBSTR( sku::STRING, \'^[^-]+-[^-]+-[^-]+\' ) ) ) ELSE sku_group END AS sku_group, from_party AS vendor_name, SUM( CASE WHEN transfer_branch_code != 32 THEN total_qty ELSE NULL END ) AS ordered, SUM( CASE WHEN transfer_branch_code = 8 THEN total_qty ELSE NULL END ) AS south, SUM( CASE WHEN transfer_branch_code = 94 THEN total_qty ELSE NULL END ) AS north FROM SNITCH_DB.MAPLEMONK.LOGIC_PURCHASE_ORDER GROUP BY 1, 2 ), puta AS ( SELECT CASE WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'SN%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'BP%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'MP%\' THEN UPPER( TRIM( REGEXP_SUBSTR( \"Item Type skuCode\"::STRING, \'^[^-]+-[^-]+-[^-]+\' ) ) ) ELSE UPPER(TRIM( COALESCE( REGEXP_SUBSTR(\"Item Type skuCode\"::STRING, \'^[^-]+-[^-]+\', 1, 1), \"Item Type skuCode\"::STRING ) )) END AS sku_group, SUM( CASE WHEN \"Warehouse Name\" = \'SAPL-WH2\' THEN putaway_completed_quantity ELSE NULL END ) AS south, SUM( CASE WHEN \"Warehouse Name\" = \'SAPL-NORTH-TAURU\' THEN putaway_completed_quantity ELSE NULL END ) AS north, SUM( CASE WHEN \"Warehouse Name\" IN (\'SAPL-NORTH-TAURU\', \'SAPL-WH2\') THEN putaway_completed_quantity ELSE NULL END ) AS inwarded, MAX( CASE WHEN \"Warehouse Name\" = \'SAPL-WH2\' AND putaway_completed_quantity >= 10 THEN putaway_updated::date ELSE NULL END ) AS south_inwarded_date, MAX( CASE WHEN \"Warehouse Name\" = \'SAPL-NORTH-TAURU\' AND putaway_completed_quantity >= 10 THEN putaway_updated::date ELSE NULL END ) AS north_inwarded_date, MAX( CASE WHEN \"Warehouse Name\" IN (\'SAPL-NORTH-TAURU\', \'SAPL-WH2\') AND putaway_completed_quantity >= 10 THEN putaway_updated::date ELSE NULL END ) AS inwarded_date FROM snitch_db.maplemonk.putaway_tracking WHERE final_type = \'New Inward\' GROUP BY 1 ), final AS ( SELECT sku_group, d.ordered, d.vendor_name, d.south South_PO, d.north North_PO, p.inwarded, p.south south_inwarded, p.north North_inwarded, p.north_inwarded_date north_inwarded_date, p.south_inwarded_date south_inwarded_date, p.inwarded_date inwarded_date, b.final_live_date, (p.inwarded / NULLIF(d.ordered, 0)) inwarded_prec, ( CASE WHEN d.south > 0 THEN 1 ELSE 0 END ) + ( CASE WHEN d.north > 0 THEN 1 ELSE 0 END ) AS PO_raised_WH_count, ( CASE WHEN p.south > 0 THEN 1 ELSE 0 END ) + ( CASE WHEN p.north > 0 THEN 1 ELSE 0 END ) AS inwarded_WH_count, CASE WHEN c.sku_group IS NULL THEN \'No Offline Allocation\' ELSE \'Offline Allocated\' END Offline_Allocated_Status FROM data d LEFT JOIN puta p USING (sku_group) LEFT JOIN snitch_db.maplemonk.product_journey b USING (sku_group) LEFT JOIN ( SELECT DISTINCT CASE WHEN UPPER(TRIM(sku)) LIKE \'SN%\' THEN UPPER(TRIM(sku)) ELSE REGEXP_REPLACE(sku, \'-[^-]+$\', \'\') END AS sku_group FROM snitch_db.maplemonk.b2b_journey ) c USING (sku_group) WHERE ordered >= 100 ), live_check as ( select distinct sku_group, live_date from snitch_db.maplemonk.category_journey ), north AS ( SELECT sku_no, planned_date, actual_delivered_date, delivery_status_type AS delivery_status_north FROM ( SELECT sku_no, COALESCE( TRY_TO_DATE(planned_date,\'DD/MM/YYYY\'), TRY_TO_DATE(planned_date,\'DD-MM-YYYY\'), TRY_TO_DATE(planned_date,\'DD-MON-YYYY\'), TRY_TO_DATE(planned_date,\'DD MON YYYY\'), TRY_TO_DATE(planned_date) ) AS planned_date, COALESCE( TRY_TO_DATE(actual_delivered_date,\'DD/MM/YYYY\'), TRY_TO_DATE(actual_delivered_date,\'DD-MM-YYYY\'), TRY_TO_DATE(actual_delivered_date,\'DD-MON-YYYY\'), TRY_TO_DATE(actual_delivered_date,\'DD MON YYYY\'), TRY_TO_DATE(actual_delivered_date) ) AS actual_delivered_date, delivery_status_type, CASE WHEN TRIM(UPPER(delivery_status_type)) IN ( \'DELEIVERED_RFID - (OUT_STATION)\', \'DELEIVERED_NON_RFID - (OUT_STATION)\' ) THEN 1 ELSE 0 END AS is_delivered, MAX(CASE WHEN TRIM(UPPER(delivery_status_type)) IN ( \'DELEIVERED_RFID - (OUT_STATION)\', \'DELEIVERED_NON_RFID - (OUT_STATION)\' ) THEN 0 ELSE 1 END) OVER (PARTITION BY sku_no) AS has_undelivered FROM snitch_db.maplemonk.tauru_inward_details_sku_level WHERE sku_no IS NOT NULL ) QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_no ORDER BY CASE WHEN has_undelivered = 1 THEN (1 - is_delivered) ELSE 0 END DESC, planned_date DESC NULLS LAST, actual_delivered_date DESC NULLS LAST ) = 1 ), south AS ( SELECT sku_no, planned_date, actual_delivered_date, delivery_status_type AS delivery_status_south FROM ( SELECT sku_no, COALESCE( TRY_TO_DATE(planned_date,\'DD/MM/YYYY\'), TRY_TO_DATE(planned_date,\'DD-MM-YYYY\'), TRY_TO_DATE(planned_date,\'DD-MON-YYYY\'), TRY_TO_DATE(planned_date,\'DD MON YYYY\'), TRY_TO_DATE(planned_date) ) AS planned_date, COALESCE( TRY_TO_DATE(actual_delivered_date,\'DD/MM/YYYY\'), TRY_TO_DATE(actual_delivered_date,\'DD-MM-YYYY\'), TRY_TO_DATE(actual_delivered_date,\'DD-MON-YYYY\'), TRY_TO_DATE(actual_delivered_date,\'DD MON YYYY\'), TRY_TO_DATE(actual_delivered_date) ) AS actual_delivered_date, delivery_status_type, MAX( CASE WHEN TRIM(delivery_status_type) = \'Not_Yet_Deleivered\' THEN 1 ELSE 0 END ) OVER (PARTITION BY sku_no) AS has_not_delivered FROM snitch_db.maplemonk.SOUTH_INWARD_DETAILS_SKU_LEVEL WHERE sku_no IS NOT NULL ) QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_no ORDER BY CASE WHEN has_not_delivered = 1 THEN CASE WHEN delivery_status_type = \'Not_Yet_Deleivered\' THEN 0 ELSE 1 END ELSE 0 END, planned_date DESC NULLS LAST, actual_delivered_date DESC NULLS LAST ) = 1 ) SELECT distinct f.sku_group, f.ordered, f.vendor_name, CASE WHEN UPPER(TRIM(REGEXP_REPLACE(f.vendor_name, \'\\s*-\\s*[^-]+$\', \'\'))) IN ( \'INDIAN CONNECTION\', \'KARMA (GU)\', \'ACME INTERNATIONAL LTD\', \'INTENSE FOCUS ITECH PRIVATE LIMITED\', \'POOJA FASHION\', \'AROMA DE FRANCE\', \'GENTEX GLOBAL\', \'A ONE KNITWEARS\', \'STELLA INDUSSTRIES LIMITED\', \'MAXVALUE CREATIONS PRIVATE LIMITED\', \'DHRUV APPARELS\', \'SAMBHAV CAP CREATION\', \'ADITYA INTERNATIONAL\', \'ANKUSH KNITTING WORKS PRIVATE LIMITED\', \'EVELINE INTERNATIONAL\', \'GOOD GOOD WEARS\', \'MAITRI KNITWEAR\', \'MANGLAM COLORS PRIVATE LIMITED\', \'MINERVA FASHION PVT LTD\', \'NEW MIGLANI HOSIERY FACTORY\', \'OBERAI KNITWEAR\', \'SHIVAAY KNITWEAR\', \'SHREE KRISHNA ENTERPRISES\', \'ADEES EXPORTS\', \'ELYSIUM FOOTWEAR CONCEPT PVT LTD\', \'LEATHER LUXURY\', \'SP INTERNATIONAL\', \'DESHNOK INNOVATOR\', \'INDIA BRAIDS PVT LTD\', \'KRISHNA BEADS INDUSTRIES\', \'AMPH FASHION PVT. LTD\', \'SHREEJI GARMENTS MANUFACTURING PVT LTD\', \'ASM INDUSTRIES (INDIA) PVT. LTD.\', \'B D SILK INDUSTRIES PVT. LTD\', \'KARMA (MU)\', \'THIMBLERR COMMERCE AND TECHNOLOGY PVT LTD\', \'EURO SUITS MANUFACTURING CO PRIVATE LIMITED\' ) THEN \'north\' WHEN UPPER(TRIM(REGEXP_REPLACE(f.vendor_name, \'\\s*-\\s*[^-]+$\', \'\'))) IN ( \'TEXPORT INDUSTRIES PVT LTD\', \'ANUVARTHH APPARELS PVT.LTD.\', \'BLUE MONKEY CLOTHING COMPANY\', \'G G GARMENTS\', \'K P GARMENT HOUSE\', \'KHARVA APPARELS\', \'LEANDRO FASHION\', \'LOHITH CREATIONS\', \'MARQUEE INDUSTRIES PVT LTD\', \'MAX KNITS INC\', \'MSQ CLOTHING LLP\', \'NALANDA DESIGNERS\', \'OM SHIVA SHAKTHI ENTERPRISES\', \'SAI TEXTILES\', \'SRI SAI TEJA CREATION\', \'V D DECORS\', \'VASUKI CREATIONS\', \'VIGNESH APPEARLS\', \'VIGNESH CREATIONS\', \'VIJAY RAM CREATIONS\', \'AMITHRAJ APPARELS\', \'KNOSKIN FASHIONS PVT. LTD\', \'VR CREATIONS\', \'ABHAY APPARELS\', \'AXCELLER\', \'DIVINITEE GENESIS APPAREL PVT LTD\', \'G T EXPORTS\', \'GO GO INTERNATIONAL PRIVATE LTD\', \'HEVIN CLOTHING\', \'KHATUSHREE INDIA\', \'KP PRODUCTION HOUSE LLP\', \'M SQUARE\', \'PRESTEIGE APPAREL PVT LTD\', \'S R APPARELS\', \'SAI TEXTILES SHADEZ\', \'THIMBLERR COMMERCE AND TECHNOLOGY PVT LTD\', \'TRIO APPARELS INDIA PVT. LTD\', \'V D FASHIONS\', \'NAVKAR AGENCY\', \'PRANAV INTERNATIONAL KNITWEAR\', \'THANDEESHWARA FASHIONS\', \'ORCHID CLOTH COMPANY\', \'HANUMAN TEXTILES\', \'ADDON CLOTHING\', \'CHECK MATE\', \'CHILLCARE APPARELS PRIVATE LIMITED\', \'ETTRO\', \'GROOVY FASHIONS\', \'LAMSOLEE CLOTHING COMPANY\', \'RAUNAK TEXTILES\', \'RENAISSANCE FASHIONS\', \'SAANVI TRADERS\', \'VISHNU TRADING CO.\', \'VISTA GLOBAL COMPANY\', \'CUT AND SEW EXPORTS\', \'VEEYA FASHION\', \'PADMA SHRI KNIT WEAR\', \'VP KNIT FASHIONS\', \'INDIANA PUNTOS CLOTHING\', \'A N ASSOCIATES\', \'ASIAN CLOTHINGS\', \'VANITHA GARMENTS\', \'WEAREVER\', \'CORE INDIA\', \'GO GO INTERNATIONAL PRIVATE LIMITED\', \'MOTIF CLOTHING CO.\', \'V.D.FASHIONS\', \'WALT ENTERPRISES\', \'VINTAGE\', \'THANDEESWARA FASHIONS\', \'SMART CLOTHING\' ) THEN \'south\' ELSE NULL END AS vendor_region, f.South_PO, f.North_PO, f.inwarded, f.south_inwarded, f.North_inwarded, f.PO_raised_WH_count, f.inwarded_WH_count, ROUND(100 * f.inwarded_prec, 1) AS inwarded_prec, CASE WHEN f.inwarded_prec >= 0.75 THEN f.inwarded_date END AS WH_Live_date, cj.image_url AS SKU_image, CASE WHEN f.sku_group LIKE \'MP%\' THEN \'Marketplace Specific SKU\' WHEN f.inwarded_prec >= 0.75 THEN \'Ready to go live\' WHEN INWARDED_WH_COUNT = 2 THEN \'Ready to go live\' WHEN f.PO_raised_WH_count < f.inwarded_WH_count THEN \'Ready to go live\' ELSE \'Not Ready to go Live\' END AS Remarks, f.Offline_Allocated_Status, CASE WHEN f.sku_group NOT LIKE \'MP%\' THEN CASE WHEN f.inwarded_prec >= 0.75 AND f.final_live_date IS NULL THEN \'Make it Live in Online\' WHEN f.inwarded_prec < 0.75 and (f.PO_Raised_WH_COUNT > INWARDED_WH_COUNT or INWARDED_WH_COUNT <= 1 ) AND f.final_live_date IS NOT NULL THEN \'Should not have made Live\' WHEN f.inwarded_prec >= 0.75 AND f.final_live_date IS NOT NULL THEN \'Already Live in Online\' WHEN f.inwarded_prec < 0.75 and (f.PO_Raised_WH_COUNT <= INWARDED_WH_COUNT ) AND f.final_live_date IS NOT NULL THEN \'Already Live in Online\' WHEN INWARDED_WH_COUNT = 2 AND f.final_live_date IS NULL THEN \'Make it Live in Online\' WHEN f.PO_Raised_WH_COUNT < INWARDED_WH_COUNT AND f.final_live_date IS NULL THEN \'Make it Live in Online\' ELSE \'Do not Make Live\' END END AS Online_Remarks, CASE WHEN f.sku_group NOT LIKE \'MP%\' THEN CASE WHEN f.inwarded_prec >= 0.75 AND f.Offline_Allocated_Status = \'No Offline Allocation\' THEN \'Make Allocation in Offline\' WHEN INWARDED_WH_COUNT = 2 AND f.Offline_Allocated_Status = \'No Offline Allocation\' THEN \'Make Allocation in Offline\' WHEN f.PO_Raised_WH_COUNT < INWARDED_WH_COUNT AND f.Offline_Allocated_Status = \'No Offline Allocation\' THEN \'Make Allocation in Offline\' WHEN f.inwarded_prec < 0.75 and (f.PO_Raised_WH_COUNT > INWARDED_WH_COUNT or INWARDED_WH_COUNT <= 1 ) AND f.Offline_Allocated_Status = \'Offline Allocated\' THEN \'Should not have made Allocations\' WHEN f.inwarded_prec >= 0.75 AND f.Offline_Allocated_Status = \'Offline Allocated\' THEN \'Offline Allocation Already Done\' WHEN f.inwarded_prec < 0.75 and (f.PO_Raised_WH_COUNT <= INWARDED_WH_COUNT ) AND f.Offline_Allocated_Status = \'Offline Allocated\' THEN \'Offline Allocation Already Done\' ELSE \'Do not Make Allocations\' END END AS Offline_Remarks, lf.live_date, north.planned_date as north_planned_date, north.actual_delivered_date AS north_actual_delivered_date, south.planned_date AS south_planned_date, south.actual_delivered_date AS south_actual_delivered_date, CASE WHEN f.north_inwarded_date IS NOT NULL AND north.actual_delivered_date IS NOT NULL AND north.actual_delivered_date > f.north_inwarded_date THEN north.actual_delivered_date ELSE f.north_inwarded_date END AS inward_date_north, CASE WHEN f.south_inwarded_date IS NOT NULL AND south.actual_delivered_date IS NOT NULL AND south.actual_delivered_date > f.south_inwarded_date THEN south.actual_delivered_date ELSE f.south_inwarded_date END AS inward_date_south, DATEDIFF( \'DAY\', north.planned_date, north.actual_delivered_date ) AS DIFF_NORTH_RECIEVED, DATEDIFF( \'DAY\', south.planned_date, south.actual_delivered_date ) AS DIFF_SOUTH_RECIEVED, north.delivery_status_north AS DELIVERY_STATUS_NORTH, south.delivery_status_south AS DELIVERY_STATUS_SOUTH FROM final f LEFT JOIN north ON f.sku_group = north.sku_no LEFT JOIN south ON f.sku_group = south.sku_no LEFT JOIN puta pw ON f.sku_group = pw.sku_group LEFT JOIN snitch_db.maplemonk.category_journey cj ON cj.sku_group = f.sku_group left join live_check lf on f.sku_group = lf.sku_group WHERE ((north.delivery_status_north ILIKE \'Not_Yet_Deleivered\' or south.delivery_status_south ILIKE \'Not_Yet_Deleivered\')or (lf.live_date > \'2026-01-01\' or lf.live_date is null)) AND UPPER(TRIM(f.sku_group)) NOT in ( \'PJ07\',\'PJ05\',\'SB4\',\'PP BINS\',\'NSB2\', \'MPB4\',\'MPB7\',\'CBB001\',\'CBS001\', \'89092763660\',\'89092763661\',\'89092763681\' ) AND UPPER(TRIM(f.sku_group)) NOT iLIKE \'NT00%\';",
                    "transaction": true
                }
            ) }}
            with sample_data as (

